#![cfg(test)]
//! Compares the host-function Poseidon with circomlibjs outputs
//! (`vectors.json`, generated by the same script as `constants.rs`).

extern crate std;

use super::*;
use soroban_sdk::{Bytes, Env};

fn hex32(env: &Env, s: &str) -> U256 {
    let mut b = [0u8; 32];
    for i in 0..32 {
        b[i] = u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap();
    }
    U256::from_be_bytes(env, &Bytes::from_array(env, &b))
}

fn vectors() -> std::vec::Vec<(std::vec::Vec<std::string::String>, std::string::String)> {
    let v: serde_json::Value = serde_json::from_str(include_str!("../../../crates/zkperp-poseidon/src/vectors.json")).unwrap();
    v["hashes"].as_array()
        .unwrap()
        .iter()
        .map(|e| {
            let ins = e["inputs"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().into()).collect();
            (ins, e["output"].as_str().unwrap().into())
        })
        .collect()
}

#[test]
fn matches_circomlibjs() {
    let env = Env::default();
    let id = env.register(PoseidonHasher, ());
    let client = PoseidonHasherClient::new(&env, &id);
    for (ins, out) in vectors() {
        let mut inputs = Vec::new(&env);
        for x in &ins {
            inputs.push_back(hex32(&env, x));
        }
        assert_eq!(client.hash(&inputs), hex32(&env, &out), "inputs {ins:?}");
    }
}

#[test]
fn rejects_input_not_in_field() {
    let env = Env::default();
    let id = env.register(PoseidonHasher, ());
    let client = PoseidonHasherClient::new(&env, &id);
    let r = U256::from_be_bytes(&env, &Bytes::from_array(&env, &R));
    let res = client.try_hash(&soroban_sdk::vec![&env, r, U256::from_u32(&env, 1)]);
    assert_eq!(res, Err(Ok(Error::InputNotInField)));
}

/// Cost of one hash running as the compiled WASM. Build first with
/// `stellar contract build`; skipped if the .wasm is missing.
#[test]
fn wasm_hash_cost() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../target/wasm32v1-none/release/poseidon.wasm");
    let Ok(wasm) = std::fs::read(path) else {
        std::println!("skipping wasm_hash_cost: {path} not found");
        return;
    };
    for (ins, out) in vectors().into_iter().filter(|(i, _)| i[0] == "0".repeat(63) + "1") {
        let env = Env::default();
        let id = env.register(wasm.as_slice(), ());
        let client = PoseidonHasherClient::new(&env, &id);
        let mut inputs = Vec::new(&env);
        for x in &ins {
            inputs.push_back(hex32(&env, x));
        }
        env.cost_estimate().budget().reset_unlimited();
        assert_eq!(client.hash(&inputs), hex32(&env, &out));
        std::println!(
            "wasm poseidon, {} inputs: cpu_insns={}",
            ins.len(),
            env.cost_estimate().budget().cpu_instruction_cost()
        );
    }
}

/// Negative control: one wrong parameter (transposed MDS) must change the
/// output, so `matches_circomlibjs` can actually catch a mismatch.
#[test]
fn wrong_parameters_disagree() {
    let env = Env::default();
    let mut mt = constants::M_T3;
    for i in 0..3 {
        for j in 0..3 {
            mt[i][j] = constants::M_T3[j][i];
        }
    }
    assert_ne!(mt, constants::M_T3, "MDS is symmetric; pick another perturbation");
    let ins = [U256::from_u32(&env, 1), U256::from_u32(&env, 2)];
    let good = Params::t3(&env).hash(&env, &ins);
    let bad = Params::new(&env, constants::ROUNDS_P_T3, &constants::C_T3, &mt).hash(&env, &ins);
    assert_ne!(good, bad);
}

/// The generated zero hashes match circomlibjs (zeros[i+1] = H(zeros[i], zeros[i])).
#[test]
fn zero_hashes_chain() {
    let env = Env::default();
    let p = Params::t3(&env);
    for i in 0..TREE_DEPTH as usize {
        let z = u256(&env, &ZEROS[i]);
        assert_eq!(p.hash(&env, &[z.clone(), z]), u256(&env, &ZEROS[i + 1]));
    }
}
